"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 trust curves on dev (analysis only, no API calls; docs/iterations.md, 2026-11-19, approved by the author).

Question: how often does each system act on a ring or knock label in the situation text, as a function of the
label's confidence, when the event is real and when it is not?
- Points: R-hear, all three versions, excluded units removed. A point has a label if its situation text lists a
  phone, doorbell or knock detection; its confidence is the highest such detection confidence.
- Real: the 8 s window holds a real phone, doorbell or knock clip (version 1). Otherwise the label is false
  (versions 2 and 3: no event, or a decoy).
- Follows the label: the system decides not to respond, the answer a real ring or knock calls for.
- Systems at their dev operating points or settings (results/main_v04/dev_report.json): ours (L1), L3, L2, T,
  B1-strong, B2-local, B2-fast, B2-strong, B3.
- Also the injection pilot's outputs (data/p1v4/runs/inject_pilot) for the local systems: one false phone label at
  every eligible point, confidences drawn from real dev false alarms; there a point's confidence is the highest of
  its injected and natural labels.
Output: results/main_v04/trust_curves_dev.json.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_trust_curves.py
"""
import json
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
PILOT = f"{R}/inject_pilot"
EVENT = ("phone", "doorbell", "knock")
EDGES = [0.0, 0.5, 0.7, 0.9, 0.99, 1.0 + 1e-9]
BINS = ["<0.5", "0.5-0.7", "0.7-0.9", "0.9-0.99", ">=0.99"]
LOCAL_SCORES = {"L1": "l1", "L3": "l3", "L2": "l2", "T": "t"}
API = {"B2-fast": "b2fast", "B2-strong": "b2strong", "B3": "b3"}
ORDER = ["L1", "L3", "L2", "T", "B1-strong", "B2-local", "B2-fast", "B2-strong", "B3"]


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def dev_decisions(rep):
    out = {}
    for n, d in LOCAL_SCORES.items():
        op = rep[n]["operating_point"]
        out[n] = S.decide(keyed(json.load(open(f"{R}/{d}/scores_dev.json"))), op["th_s"], op["th_r"])
    out["B1-strong"] = keyed(json.load(open(f"{R}/b1/decisions_dev.json")))
    op = rep["B2-local"]["operating_point"]
    sc = keyed(json.load(open(f"{R}/b2local/scores_dev_K{op['K']}_{op['reading']}.json")))
    out["B2-local"] = S.decide(sc, op["th_s"], op["th_r"])
    for n, d in API.items():
        op = rep[n]["operating_point"]
        sc = keyed(json.load(open(f"{R}/api/{d}/scores_dev_{op['setting']}.json")))
        out[n] = S.decide(sc, op["th_s"], op["th_r"])
    return out


def pilot_decisions(rep):
    out = {}
    for n in LOCAL_SCORES:
        op = rep[n]["operating_point"]
        out[n] = S.decide(keyed(json.load(open(f"{PILOT}/scores_{n}.json"))), op["th_s"], op["th_r"])
    out["B1-strong"] = keyed(json.load(open(f"{PILOT}/decisions_B1.json")))
    return out


def r_hear_points(rows, ctx, injected=None):
    ex = S.excluded_units()
    pts = []
    for r in rows:
        if r["part"] != "r_hear" or r["unit"] in ex:
            continue
        for p in r["points"]:
            real = any(c in EVENT for c, _, _ in D.window_events(r, p["t"]))
            conf = [s[3] for s in ctx.point(r, p["k"])[3] if s[0] in EVENT]
            if injected is not None:
                e = injected.get(f"{r['unit']}|{r['version']}|{p['k']}")
                if e:
                    conf.append(e[3])
            pts.append({"key": (r["unit"], r["version"], p["k"]), "real": real,
                        "conf": max(conf) if conf else None, "gold": p["gold"]["R"]})
    return pts


def curve(pts, dec, follow_value, real):
    out = {}
    for lo, hi, b in zip(EDGES[:-1], EDGES[1:], BINS):
        sel = [q for q in pts if q["real"] == real and q["conf"] is not None and lo <= q["conf"] < hi]
        f = [dec.get(q["key"], {}).get("R") == follow_value for q in sel]
        out[b] = {"n": len(sel), "follow": float(np.mean(f)) if f else None}
    sel = [q for q in pts if q["real"] == real and q["conf"] is None]
    f = [dec.get(q["key"], {}).get("R") == follow_value for q in sel]
    out["no label"] = {"n": len(sel), "follow": float(np.mean(f)) if f else None}
    return out


def fmt(c):
    parts = []
    for b in BINS + ["no label"]:
        x = c[b]
        v = "  -  " if x["follow"] is None else f"{x['follow']:.2f}"
        parts.append(f"{b}:{v}({x['n']})")
    return " ".join(parts)


def main():
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    rows = D.load_rows("dev")
    ctx = C.Context("dev")
    pts = r_hear_points(rows, ctx)
    gold_real = {q["gold"] for q in pts if q["real"]}
    assert len(gold_real) == 1, gold_real
    follow_value = gold_real.pop()
    res = {"follow_value": follow_value, "bins": BINS, "dev": {}, "injected": {}}
    dec = dev_decisions(rep)
    for n in ORDER:
        res["dev"][n] = {"real": curve(pts, dec[n], follow_value, True),
                         "false": curve(pts, dec[n], follow_value, False)}
    inj = json.load(open(f"{PILOT}/injections.json"))
    ipts = r_hear_points(rows, ctx, inj)
    idec = pilot_decisions(rep)
    for n in ["L1", "L3", "L2", "T", "B1-strong"]:
        res["injected"][n] = {"false": curve(ipts, idec[n], follow_value, False)}
    json.dump(res, open("results/main_v04/trust_curves_dev.json", "w"), indent=1)
    print(f"follow = decision R == {follow_value!r}; bins of the highest ring/knock label confidence")
    for n in ORDER:
        print(f"{n:10s} real : {fmt(res['dev'][n]['real'])}")
        print(f"{'':10s} false: {fmt(res['dev'][n]['false'])}")
    print("injection pilot (false labels at every eligible point):")
    for n, x in res["injected"].items():
        print(f"{n:10s} false: {fmt(x['false'])}")


if __name__ == "__main__":
    main()
